// def tree_v(t: RTree) -> int32:
//     if isinstance(t, A):
//         return t.v
//     if isinstance(t, str):
//         return 1
//     return 0
int32_t tree_v(const RTree& t) {
    if (std::holds_alternative<A>(t.value)) {
        const auto& __t = std::get<A>(t.value);
        return __t.v;
    }
    if (std::holds_alternative<std::string>(t.value)) {
        const auto& __t = std::get<std::string>(t.value);
        return 1;
    }
    return 0;
}

